// Get all sitemap URLs for this domain from the pages table
const d = $input.item.json;
return [{ json: { 
  domain_id: d.domain_id, 
  domain: d.domain,
  phase: 'get_sitemaps'
}}];

// Deep sitemap parser - fetches and recursively parses all sitemaps
// Handles: sitemap index, urlset, gzip, namespaces

const prepData = $('Prep Domain').item.json;
const sitemapRows = $input.all();
const domain = prepData.domain;
const domain_id = prepData.domain_id;

// Collect sitemap URLs from DB
const sitemapUrls = sitemapRows
  .map(r => r.json.url)
  .filter(u => u && u.includes('sitemap'));

console.log(`[W-3B] Processing ${sitemapUrls.length} sitemaps for ${domain}`);

let allDiscoveredUrls = [];
let processedSitemaps = new Set();

// Helper: Parse sitemap XML with namespace tolerance
function parseSitemap(xml) {
  const result = { urls: [], sitemaps: [] };
  if (!xml || typeof xml !== 'string' || xml.length < 50) return result;

  // Clean XML
  let clean = xml.replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '');

  // Check if this is a sitemap index
  const isSitemapIndex = clean.includes('<sitemapindex') || 
                         (clean.includes('<sitemap>') && !clean.includes('<urlset'));

  // Extract <loc> URLs - handle various namespace patterns
  const locPattern = /<(?:[a-z0-9]+:)?loc>\s*([^<]+)\s*<\/(?:[a-z0-9]+:)?loc>/gi;
  let match;
  while ((match = locPattern.exec(clean)) !== null) {
    const url = match[1].trim();
    if (url && url.startsWith('http')) {
      // Is this a child sitemap or a content URL?
      const isChildSitemap = url.endsWith('.xml') || 
                             url.endsWith('.xml.gz') || 
                             url.includes('sitemap');

      if (isSitemapIndex && isChildSitemap) {
        result.sitemaps.push(url);
      } else if (!isChildSitemap) {
        result.urls.push(url);
      } else if (!isSitemapIndex) {
        // In a urlset, treat everything as content unless clearly a sitemap
        result.urls.push(url);
      }
    }
  }

  return result;
}

// Fetch helper
async function fetchSitemap(url) {
  try {
    const resp = await this.helpers.request({
      method: 'GET',
      url: url,
      timeout: 15000,
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; AMI-Bot/1.0)',
        'Accept': 'application/xml, text/xml, */*',
        'Accept-Encoding': 'gzip, deflate'
      },
      resolveWithFullResponse: false,
      simple: false
    });

    if (typeof resp === 'string') return resp;
    if (resp && resp.body) return resp.body;
    return '';
  } catch (e) {
    console.log(`[W-3B] Failed to fetch ${url}: ${e.message}`);
    return '';
  }
}

// Process all sitemaps recursively (max 3 levels)
async function processSitemap(url, depth = 0) {
  if (depth > 3 || processedSitemaps.has(url) || allDiscoveredUrls.length > 1000) {
    return;
  }

  processedSitemaps.add(url);
  console.log(`[W-3B] Parsing sitemap (depth ${depth}): ${url}`);

  const xml = await fetchSitemap.call(this, url);
  if (!xml) return;

  const parsed = parseSitemap(xml);
  console.log(`[W-3B] Found ${parsed.urls.length} URLs, ${parsed.sitemaps.length} child sitemaps`);

  // Add discovered URLs
  allDiscoveredUrls = allDiscoveredUrls.concat(parsed.urls);

  // Recursively process child sitemaps
  for (const childUrl of parsed.sitemaps) {
    await processSitemap.call(this, childUrl, depth + 1);
  }
}

// Process all known sitemaps
for (const sitemapUrl of sitemapUrls) {
  await processSitemap.call(this, sitemapUrl, 0);
}

// Dedupe and filter
const uniqueUrls = [...new Set(allDiscoveredUrls)];

console.log(`[W-3B] Total unique URLs discovered: ${uniqueUrls.length}`);

if (uniqueUrls.length === 0) {
  return [{ json: { domain_id, domain, _skip: true, urls_found: 0 }}];
}

// Return URLs for insertion (limit to 500 per run)
return uniqueUrls.slice(0, 500).map(url => ({ json: { domain_id, domain, url }}));

// Aggregate results - get domain from input items (each item has domain_id/domain)
const items = $input.all();
const urlsInserted = items.filter(i => i.json.url).length;

// Get domain info from first item (all items have same domain)
let domain_id = '';
let domain = '';
if (items.length > 0 && items[0].json) {
  domain_id = items[0].json.domain_id || '';
  domain = items[0].json.domain || '';
}

console.log(`[W-3B] Inserted ${urlsInserted} URLs for ${domain}`);

return [{ json: { 
  domain_id: domain_id, 
  domain: domain, 
  urls_inserted: urlsInserted 
}}];

// Handle skip case - get domain from input item
const item = $input.item.json;
return [{ json: { domain_id: item.domain_id || '', domain: item.domain || '', urls_inserted: 0 }}];
